const state={day:1,actions:2,resources:{scrap:42,food:36,fuel:18,meds:5},morale:72,wall:64,foodDays:0,ration:'Vừa đủ',buildings:{wall:1,tower:0,barracks:0},soldiers:[{name:'Linh',role:'Xạ thủ',damage:7,icon:'◉',hp:100},{name:'Bảo',role:'Lính gác',damage:5,icon:'▰',hp:100}],log:[{day:1,text:'Trạm 07 bắt được tín hiệu cứu hộ yếu. Có người đang chờ bạn dẫn đường.',tone:'good'},{day:1,text:'Đội tuần tra báo cáo: phía bắc có chuyển động trong màn sương.',tone:''},{day:0,text:'Cửa kho đã khóa. Nhiên liệu dự trữ chỉ còn vài can.',tone:'bad'}],gameOver:false,selectedTab:'tất cả'};
const $=s=>document.querySelector(s), fmt=n=>Math.floor(n).toLocaleString('vi-VN');
const resourceInfo=[['scrap','▧','Sắt vụn','var(--orange)'],['food','◒','Lương thực','var(--lime)'],['fuel','◈','Nhiên liệu','var(--blue)'],['meds','✚','Thuốc men','var(--red)']];
const buildingInfo={wall:{name:'Tường chắn',icon:'▤',desc:'Lớp phòng thủ đầu tiên. Chặn sát thương tràn vào căn cứ.',base:{scrap:28},stat:'Máu tường'},tower:{name:'Tháp canh',icon:'♜',desc:'Tăng tầm quan sát, giúp phát hiện đợt tấn công sớm.',base:{scrap:34,fuel:5},stat:'Sức phòng thủ'},barracks:{name:'Doanh trại',icon:'⌂',desc:'Chỗ nghỉ cho lính. Tăng tinh thần và khả năng phòng thủ.',base:{scrap:40,food:8},stat:'Sức chứa lính'}};
const missions=[{id:'scrap',icon:'⚒',title:'Bãi xe đổ nát',text:'Lục soát xe cũ, tìm linh kiện và sắt vụn.',gain:'Sắt vụn +18–28',risk:'Rủi ro thấp'},{id:'food',icon:'♧',title:'Siêu thị hoang',text:'Kho hàng cũ có thể còn đồ hộp dùng được.',gain:'Lương thực +14–22',risk:'Rủi ro vừa'},{id:'fuel',icon:'◈',title:'Trạm xăng số 4',text:'Bồn chứa nguy hiểm nhưng nhiên liệu rất cần.',gain:'Nhiên liệu +10–17',risk:'Rủi ro cao'}];
function log(text,tone=''){state.log.unshift({day:state.day,text,tone});state.log=state.log.slice(0,6)}
function has(cost){return Object.entries(cost).every(([k,v])=>state.resources[k]>=v)}
function spend(cost){for(const [k,v] of Object.entries(cost))state.resources[k]-=v}
function costText(cost){return Object.entries(cost).map(([k,v])=>`${v} ${({scrap:'sắt',food:'thức ăn',fuel:'nhiên liệu',meds:'thuốc'})[k]}`).join(' · ')}
function render(){
 $('#dayLabel').textContent=`NGÀY ${String(state.day).padStart(2,'0')}`;$('#dateLabel').textContent=`Sau sụp đổ: ${213+state.day}`;$('#apLabel').textContent=`${state.actions} / 2`;$('#endDay').disabled=state.gameOver;
 $('#resourcebar').innerHTML=resourceInfo.map(([key,icon,name,color])=>`<div class="resource"><div class="res-icon" style="color:${color}">${icon}</div><div><strong>${fmt(state.resources[key])}</strong><small>${name}</small></div></div>`).join('')+`<div class="resource"><div class="res-icon" style="color:var(--blue)">♟</div><div><strong>${state.soldiers.length}</strong><small>Đội phòng thủ</small></div><span class="delta">${state.actions} ⚡</span></div>`;
 $('#scavengeCards').innerHTML=missions.map(m=>`<button class="action-card" data-mission="${m.id}" ${state.actions<1||state.gameOver?'disabled':''}><div class="card-icon">${m.icon}</div><div><strong>${m.title}</strong><p>${m.text}</p></div><div class="card-meta"><span>${m.gain}</span><span class="risk">${m.risk}</span></div></button>`).join('');
 document.querySelectorAll('[data-mission]').forEach(b=>b.onclick=()=>scavenge(b.dataset.mission));
 renderBuildings();renderStatus();renderThreat();renderLog();drawMap();
}
function renderBuildings(){const list=$('#buildingList');$('#buildingCount').textContent=`${Object.values(state.buildings).reduce((a,b)=>a+b,0)} công trình`;list.innerHTML=Object.entries(buildingInfo).map(([id,b])=>{let level=state.buildings[id],cost=Object.fromEntries(Object.entries(b.base).map(([k,v])=>[k,v+Math.max(0,level-1)*Math.ceil(v*.55)]));let label=level?'NÂNG CẤP':'XÂY DỰNG';return `<div class="manage-item"><div class="manage-icon">${b.icon}</div><div><strong>${b.name} · Cấp ${level}</strong><small>${b.desc}</small><small class="cost">${costText(cost)}</small></div><button class="mini-btn" data-build="${id}" ${(!has(cost)||state.gameOver)?'disabled':''}>${label}</button></div>`}).join('');document.querySelectorAll('[data-build]').forEach(b=>b.onclick=()=>build(b.dataset.build))}
function renderStatus(){let foodPer=state.ration==='Thrifty'?Math.ceil(state.soldiers.length*.65):state.ration==='No'?0:state.ration==='Generous'?state.soldiers.length*2:state.soldiers.length;let foodPct=state.resources.food?Math.min(100,state.resources.food/(Math.max(1,state.soldiers.length*3))*100):0;let items=[['Tinh thần',state.morale,'Mức độ tin tưởng và ý chí chiến đấu',state.morale<30?'red':state.morale<55?'orange':''],['Tường thành',state.wall,'Khả năng chống chịu trước đợt tấn công',state.wall<30?'red':'orange'],['Lương thực',foodPct,`Khẩu phần ${state.ration.toLowerCase()} · ${foodPer} đơn vị / đêm`,foodPct<30?'red':'']];$('#statusBars').innerHTML=items.map(([name,pct,desc,color])=>`<div class="status-row"><div class="status-label"><span>${name}</span><span>${name==='Lương thực'?`${fmt(state.resources.food)} · `:''}${Math.round(pct)}%</span></div><div class="bar"><div class="bar-fill ${color}" style="width:${Math.max(0,pct)}%"></div></div><div style="font-size:9px;color:var(--muted);margin-top:5px">${desc}</div></div>`).join('');$('#teamCount').textContent=`${state.soldiers.length} người · ${state.soldiers.reduce((a,s)=>a+s.damage,0)} hỏa lực`;$('#soldiers').innerHTML=state.soldiers.length?state.soldiers.map(s=>`<div class="soldier-chip"><div class="soldier-avatar">${s.icon}</div><div>${s.name}<small>${s.role} · ${s.damage} SM</small></div></div>`).join(''):'<span class="subtle">Chưa có lính — hãy tuyển mộ!</span>';$('#rationList').innerHTML=`<div class="manage-item"><div class="manage-icon">♨</div><div><strong>Khẩu phần mỗi đêm</strong><small>Ưu tiên giữa tiết kiệm lương thực và tinh thần.</small></div><select class="ration-select" id="ration"><option ${state.ration==='Thrifty'?'selected':''}>Thrifty</option><option ${state.ration==='Vừa đủ'?'selected':''}>Vừa đủ</option><option ${state.ration==='Generous'?'selected':''}>Generous</option><option ${state.ration==='No'?'selected':''}>No</option></select></div>`;$('#ration').innerHTML=`<option value="Thrifty" ${state.ration==='Thrifty'?'selected':''}>Tiết kiệm</option><option value="Vừa đủ" ${state.ration==='Vừa đủ'?'selected':''}>Vừa đủ</option><option value="Generous" ${state.ration==='Generous'?'selected':''}>Hào phóng</option><option value="No" ${state.ration==='No'?'selected':''}>Nhịn ăn</option>`;$('#ration').onchange=e=>{state.ration=e.target.value;render();toast('Đã thay đổi khẩu phần')};}
function renderThreat(){let remaining=4-((state.day-1)%4);$('#waveLabel').textContent=`CÒN ${remaining} NGÀY`;let power=12+Math.floor((state.day-1)/4)*5;$('#threatPower').textContent=power;$('#threatProgress').style.width=`${((4-remaining+1)/4)*100}%`;$('#threatType').textContent=state.day%8<4?'BÓNG ĐEN DI CHUYỂN':'TÍN HIỆU CƯỚP ĐƯỜNG';$('#threatDescription').textContent=state.day%8<4?'Chuyển động lạ ở phía bắc. Có thể là xác sống lang thang… hoặc một toán cướp.':'Một nhóm người có vũ trang đang dò xét hàng rào. Chúng sẽ thử sức phòng thủ của bạn.';$('#baseCondition').textContent=state.wall>60?'Hàng rào còn trụ vững':state.wall>25?'Hàng rào cần được gia cố':'Hàng rào sắp đổ!';}
function renderLog(){$('#eventLog').innerHTML=state.log.slice(0,5).map(x=>`<div class="log-item"><span class="log-time">N${String(x.day).padStart(2,'0')}</span><p class="${x.tone}">${x.text}</p></div>`).join('')}
function toast(msg){const el=$('#toast');el.textContent=msg;el.classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>el.classList.remove('show'),2100)}

