function toast(msg){const el=$('#toast');el.textContent=msg;el.classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>el.classList.remove('show'),2100)}
function scavenge(id){if(state.actions<1||state.gameOver)return;let m=missions.find(x=>x.id===id);state.actions--;let found= id==='scrap'?rand(18,28):id==='food'?rand(14,22):rand(10,17);state.resources[id]+=found;let danger=id==='scrap'?10:id==='food'?18:28;let trouble=Math.random()*100<danger;if(trouble){let injury=Math.random()<.5&&state.soldiers.length>0;if(injury){let s=state.soldiers[Math.floor(Math.random()*state.soldiers.length)];s.hp-=20;state.morale=Math.max(0,state.morale-4);log(`${s.name} bị thương trong chuyến đi. Đội phải rút lui.`, 'bad')}else{let loss=Math.min(state.resources[id],rand(2,5));state.resources[id]-=loss;log(`Đoàn thám hiểm chạm trán nguy hiểm, thất thoát ${loss} đơn vị hàng hóa.`, 'bad')}}else log(`Chuyến đi thành công: thu được ${found} ${id==='scrap'?'sắt vụn':id==='food'?'lương thực':'nhiên liệu'}.`,'good');render();toast(trouble?'Chuyến đi gặp sự cố!':`Thu được ${found} ${id==='scrap'?'sắt vụn':id==='food'?'lương thực':'nhiên liệu'}`)}
function rand(a,b){return Math.floor(Math.random()*(b-a+1))+a}
function build(id){let level=state.buildings[id],base=buildingInfo[id].base,cost=Object.fromEntries(Object.entries(base).map(([k,v])=>[k,v+Math.max(0,level-1)*Math.ceil(v*.55)]));if(!has(cost))return;spend(cost);state.buildings[id]++;if(id==='wall')state.wall=Math.min(100,state.wall+28);if(id==='tower')state.morale=Math.min(100,state.morale+3);log(`${level?'Nâng cấp':'Xây dựng'} ${buildingInfo[id].name} hoàn tất. Căn cứ được củng cố.`,'good');render();toast(`${buildingInfo[id].name} · cấp ${state.buildings[id]}`)}
function openRecruit(){const people=[{name:'Tâm',role:'Bắn tỉa',damage:9,icon:'◉',cost:{scrap:18,food:6},note:'Sát thương cao · Khó tuyển'},{name:'Hạnh',role:'Y tá',damage:3,icon:'✚',cost:{scrap:12,food:5,meds:1},note:'Giỏi sơ cứu · Giảm tổn thất'},{name:'Quân',role:'Trinh sát',damage:5,icon:'⌖',cost:{scrap:14,food:5,fuel:2},note:'Tầm nhìn xa · Khám phá an toàn'},{name:'Đạt',role:'Lính gác',damage:6,icon:'▰',cost:{scrap:16,food:5},note:'Cân bằng · Đáng tin cậy'}];showModal(`<div class="eyebrow">CHỢ ĐEN VEN ĐƯỜNG</div><h2>Tuyển người sống sót</h2><p>Chọn người phù hợp với kế hoạch phòng thủ. Tuyển mộ không tiêu tốn hành động nhưng cần lương thực mỗi đêm.</p><div class="choice-list">${people.map((p,i)=>`<button class="choice" data-hire="${i}" ${!has(p.cost)||state.soldiers.length>=8?'disabled':''}><span><strong>${p.icon} ${p.name} · ${p.role}</strong><small>${p.note}</small><small class="cost">${costText(p.cost)}</small></span><span class="stats">${p.damage} SM</span></button>`).join('')}</div><div class="modal-actions"><button class="modal-close" data-close>ĐÓNG</button></div>`);document.querySelectorAll('[data-hire]').forEach(b=>b.onclick=()=>{let p=people[+b.dataset.hire];if(!has(p.cost)||state.soldiers.length>=8)return;spend(p.cost);state.soldiers.push({...p,hp:100});state.morale=Math.min(100,state.morale+2);log(`${p.name}, ${p.role}, gia nhập đội phòng thủ.`,'good');closeModal();render();toast(`${p.name} đã gia nhập đội!`)});}
function showModal(html){$('#modal').innerHTML=html;$('#modalBackdrop').classList.add('open');document.querySelectorAll('[data-close]').forEach(b=>b.onclick=closeModal)}function closeModal(){$('#modalBackdrop').classList.remove('open')}
function endDay(){if(state.gameOver)return;let ration=state.ration==='Tiết kiệm'?Math.ceil(state.soldiers.length*.65):state.ration==='Hào phóng'?state.soldiers.length*2:state.ration==='Nhịn ăn'?0:state.soldiers.length;if(state.resources.food>=ration){state.resources.food-=ration;if(state.ration==='Hào phóng')state.morale=Math.min(100,state.morale+4);else if(state.ration==='Tiết kiệm')state.morale=Math.max(0,state.morale-2);else if(state.ration==='Nhịn ăn')state.morale=Math.max(0,state.morale-12);else state.morale=Math.max(0,state.morale-1)}else{state.resources.food=0;state.morale=Math.max(0,state.morale-14);log('Kho lương trống rỗng. Cả đội phải đi ngủ với bụng đói.','bad')}
 state.day++;state.actions=2;if(state.day%4===1){raid();}else{log(`Đêm ${String(state.day).padStart(2,'0')} trôi qua yên ổn. Căn cứ vẫn an toàn.`)}if(state.morale<20){log('Tinh thần suy sụp. Có người đang tính chuyện rời đi.','bad');if(state.soldiers.length>1&&Math.random()<.35){let left=state.soldiers.pop();log(`${left.name} đã rời trạm trong đêm.`,'bad')}}if(state.wall<=0){state.gameOver=true;showModal(`<div class="eyebrow gameover">TRẠM ĐÃ THẤT THỦ</div><h2>Ánh đèn tắt giữa vùng tro</h2><p>Đội không thể giữ vững vành đai. Bạn đã sống sót đến ngày ${state.day}. Mỗi quyết định đều có giá của nó.</p><div class="modal-actions"><button class="mini-btn" id="restart">CHƠI LẠI</button></div>`);$('#restart').onclick=()=>location.reload()}render()}
function raid(){let enemy=12+Math.floor((state.day-1)/4)*5+(Math.random()<.5?0:4);let defense=state.soldiers.reduce((a,s)=>a+s.damage,0)+state.buildings.wall*4+state.buildings.tower*8+state.buildings.barracks*2;let towerBonus=state.buildings.tower?4:0;let power=defense+towerBonus+Math.floor(state.morale/20);let label=state.day%8<4?'bầy xác sống':'toán cướp đường';if(power>=enemy){let loss=Math.max(0,Math.ceil((enemy-power)*.35));state.wall=Math.max(0,state.wall-loss);state.resources.scrap=Math.max(0,state.resources.scrap-Math.ceil(loss/3));state.morale=Math.min(100,state.morale+3);log(`Đợt ${label} (${enemy} sức mạnh) bị đẩy lùi! Thiệt hại tường: ${loss}.`,'good')}else{let damage=Math.min(48,Math.ceil((enemy-power)*1.6)+rand(5,12));state.wall=Math.max(0,state.wall-damage);let wounded=state.soldiers.length&&Math.random()<.6?state.soldiers[rand(0,state.soldiers.length-1)]:null;if(wounded){wounded.hp-=rand(25,55);if(wounded.hp<=0){state.soldiers=state.soldiers.filter(s=>s!==wounded);log(`${wounded.name} đã hy sinh khi giữ cửa trạm.`,'bad')}else log(`${wounded.name} bị thương trong đợt tấn công.`,'bad')}state.morale=Math.max(0,state.morale-10);log(`Đợt ${label} áp đảo tuyến phòng thủ! Tường mất ${damage} độ bền.`,'bad')}}
$('#endDay').onclick=endDay;$('#recruitButton').onclick=openRecruit;$('#modalBackdrop').onclick=e=>{if(e.target.id==='modalBackdrop')closeModal()};

