function build(id){let level=state.buildings[id],base=buildingInfo[id].base,cost=Object.fromEntries(Object.entries(base).map(([k,v])=>[k,v+Math.max(0,level-1)*Math.ceil(v*.55)]));if(!has(cost))return;spend(cost);state.buildings[id]++;if(id==='wall')state.wall=Math.min(100,state.wall+28);if(id==='tower')state.morale=Math.min(100,state.morale+3);log(`${level?'Nâng cấp':'Xây dựng'} ${buildingInfo[id].name} hoàn tất. Căn cứ được củng cố.`,'good');render();toast(`${buildingInfo[id].name} · cấp ${state.buildings[id]}`)}
function openRecruit(){const people=[{name:'Tâm',role:'Bắn tỉa',damage:9,icon:'◉',cost:{scrap:18,food:6},note:'Sát thương cao · Khó tuyển'},{name:'Hạnh',role:'Y tá',damage:3,icon:'✚',cost:{scrap:12,food:5,meds:1},note:'Giỏi sơ cứu · Giảm tổn thất'},{name:'Quân',role:'Trinh sát',damage:5,icon:'⌖',cost:{scrap:14,food:5,fuel:2},note:'Tầm nhìn xa · Khám phá an toàn'},{name:'Đạt',role:'Lính gác',damage:6,icon:'▰',cost:{scrap:16,food:5},note:'Cân bằng · Đáng tin cậy'}];showModal(`<div class="eyebrow">CHỢ ĐEN VEN ĐƯỜNG</div><h2>Tuyển người sống sót</h2><p>Chọn người phù hợp với kế hoạch phòng thủ. Tuyển mộ không tiêu tốn hành động nhưng cần lương thực mỗi đêm.</p><div class="choice-list">${people.map((p,i)=>`<button class="choice" data-hire="${i}" ${!has(p.cost)||state.soldiers.length>=8?'disabled':''}><span><strong>${p.icon} ${p.name} · ${p.role}</strong><small>${p.note}</small><small class="cost">${costText(p.cost)}</small></span><span class="stats">${p.damage} SM</span></button>`).join('')}</div><div class="modal-actions"><button class="modal-close" data-close>ĐÓNG</button></div>`);document.querySelectorAll('[data-hire]').forEach(b=>b.onclick=()=>{let p=people[+b.dataset.hire];if(!has(p.cost)||state.soldiers.length>=8)return;spend(p.cost);state.soldiers.push({...p,hp:100});state.morale=Math.min(100,state.morale+2);log(`${p.name}, ${p.role}, gia nhập đội phòng thủ.`,'good');closeModal();render();toast(`${p.name} đã gia nhập đội!`)});}
