urce small{font-size:10px;color:var(--muted)}.resource .delta{margin-left:auto;color:var(--lime);font:10px var(--mono)}.main-grid{display:grid;grid-template-columns:minmax(0,1.65fr) minmax(330px,.92fr);gap:16px;align-items:start}.leftcol,.rightcol{display:grid;gap:14px}.panel{background:linear-gradient(155deg,#1d241f,#171c19);border:1px solid var(--line);border-radius:12px;overflow:hidden}.panel-head{padding:14px 16px 12px;display:flex;justify-content:space-between;align-items:center;border-bottom:1px solid #2a332d}.panel-title{font-size:12px;font-weight:800;letter-spacing:.5px;display:flex;gap:8px;align-items:center}.panel-title .dot{width:7px;height:7px;border-radius:50%;background:var(--lime);box-shadow:0 0 9px #c6e36a77}.subtle{font:10px var(--mono);color:var(--muted)}.map-wrap{position:relative;background:#202820;padding:0;min-height:330px}.map-canvas{display:block;width:100%;height:auto;min-height:330px;max-height:405px;object-fit:cover}.map-label{position:absolute;left:15px;top:14px;font:10px var(--mono);color:#e5e9d8;background:#101713b8;padding:6px 9px;border-radius:5px;backdrop-filter:blur(4px)}.map-coords{position:absolute;right:13px;bottom:12px;font:9px var(--mono);color:#d0d6c1a8}.base-footer{display:flex;align-items:center;justify-content:space-between;padding:11px 15px}.condition{display:flex;align-items:center;gap:7px;font-size:11px}.condition i{width:7px;height:7px;border-radius:50%;background:var(--lime)}.map-legend{display:flex;gap:12px;color:var(--muted);font-size:10px}.map-legend span{display:flex;align-items:center;gap:5px}.legend-dot{width:7px;height:7px;border-radius:2px;background:#a4b95d}.ap-pill{font:10px var(--mono);color:var(--orange);border:1px solid #634a35;border-radius:20px;padding:5px 8px;white-space:nowrap}.action-content{padding:14px 15px 15px}.action-intro{display:flex;justify-content:space-between;align-items:flex-start;margin-bottom:12px}.action-intro h3{margin:0 0 4px;font-size:13px}.action-intro p{margin:0;font-size:10px;color:var(--muted);line-height:1.5}.cards{display:grid;grid-template-columns:repeat(3,1fr);gap:9px}.action-card{border:1px solid #354037;border-radius:9px;background:#202822;padding:11px;text-align:left;transition:.15s;position:relative;min-width:0}.action-card:hover{border-color:#71804a;background:#283329;transform:translateY(-2px)}.action-card:disabled{opacity:.42;cursor:not-allowed;transform:none}.card-icon{font-size:19px;margin-bottom:7px}.action-card strong{display:block;font-size:11px;margin-bottom:4px}.action-card p{color:var(--muted);font-size:9px;line-height:1.5;margin:0;min-height:27px}.card-meta{margin-top:8px;padding-top:7px;border-top:1px solid #303a33;display:flex;justify-content:space-between;font:9px var(--mono);color:var(--lime)}.card-meta .risk{color:var(--orange)}.side-panel{padding-bottom:2px}.status-row{padding:12px 15px;border-bottom:1px solid #2a332d}.status-row:last-child{border-bottom:0}.status-label{display:flex;justify-content:space-between;font-size:10px;margin-bottom:7px}.status-label span:last-child{font:10px var(--mono);color:var(--muted)}.bar{height:5px;background:#333c35;border-radius:6px;overflow:hidden}.bar-fill{height:100%;border-radius:6px;background:var(--lime);transition:width .4s}.bar-fill.orange{background:var(--orange)}.bar-fill.red{background:var(--red)}.team-summary{display:flex;justify-content:space-between;align-items:center;padding:11px 15px}.team-summary strong{font-size:11px}.team-summary span{color:var(--muted);font-size:10px}.soldiers{display:flex;gap:7px;padding:0 15px 14px;flex-wrap:wrap}.soldier-chip{display:flex;align-items:center;gap:7px;border:1px solid #354037;background:#202822;padding:6px 8px;border-radius:7px;font-size:9px}.soldier-avatar{width:23px;height:23px;display:grid;place-items:center;border-radius:6px;background:#384331;color:#cfdd98}.soldier-chip small{display:block;color:var(--muted);font:8px var(--mono);margin-top:1px}.threat{padding:14px 15px 15px}.threat-top{display:flex;justify-content:space-between;align-items:center}.threat-type{color:var(--red);font-size:11px;font-weight:700}.threat-number{font:700 20px var(--mono)}.threat p{margin:5px 0 11px;color:var(--muted);font-size:10px;line-height:1.55}.threat-line{height:4px;background:#343a32;border-radius:8px;overflow:hidden}.threat-line div{height:100%;width:40%;background:linear-gradient(90deg,var(--orange),var(--red));border-radius:8px}.log-list{padding:4px 15px 10px}.log-item{display:flex;gap:9px;padding:8px 0;border-bottom:1px solid #2a332d;font-size:10px;line-height:1.45}.log-item:last-child{border:0}.log-time{font:9px var(--mono);color:#7d897f;white-space:nowrap}.log-item p{margin:0;color:#c5cdc2}.log-item .good{color:var(--lime)}.log-item .bad{color:var(--orange)}.secondary-grid{display:grid;grid-template-columns:1fr 1fr;gap:12px}.manage-panel{padding-bottom:12px}.manage-panel .panel-head{padding-bottom:11px}.manage-list{padding:6px 12px 0}.manage-item{display:grid;grid-template-columns:35px 1fr auto;gap:9px;align-items:center;padding:9px 3px;border-bottom:1px solid #2b342d}.manage-item:last-child{border:0}.manage-icon{height:32px;border-radius:8px;background:#2b352d;display:grid;place-items:center;font-size:16px}.manage-item strong{display:block;font-size:10px}.manage-item small{display:block;color:var(--muted);font-size:9px;margin-top:3px;line-height:1.3}.mini-btn{border:1px solid #52603d;border-radius:6px;background:#323d2c;color:var(--lime);padding:6px 8px;font-size:9px;font-weight:700;white-space:nowrap}.mini-btn:hover{background:#465539}.mini-btn:disabled{opacity:.38;cursor:not-allowed}.cost{font:8px var(--mono);color:#b4c08e}.ration-select{background:#202822;color:var(--text);border:1px solid #45513f;border-radius:6px;padding:6px;font-size:9px}.hint{font-size:9px;color:var(--muted);padding:0 15px;line-height:1.55}.toast{position:fixed;left:50%;bottom:22px;transform:translate(-50%,20px);background:#d4e98b;color:#1b2318;font-weight:700;padding:10px 15px;border-radius:8px;opacity:0;pointer-events:none;transition:.22s;box-shadow:0 8px 30px #0008;z-index:5;font-size:11px}.toast.show{opacity:1;transform:translate(-50%,0)}.modal-backdrop{position:fixed;inset:0;background:#080b09c9;display:none;place-items:center;z-index:4;padding:18px}.modal-backdrop.open{display:grid}.modal{width:min(440px,100%);background:#202822;border:1px solid #4a5749;border-radius:13px;padding:21px;box-shadow:0 20px 70px #0009}.modal h2{margin:0 0 6px;font-size:16px}.modal p{color:var(--muted);font-size:11px;line-height:1.6}.choice-list{display:grid;gap:8px;margin:14px 0}.choice{width:100%;text-align:left;background:#29332c;border:1px solid #3c493f;border-radius:8px;padding:10px;display:flex;justify-content:space-between;align-items:center}.choice:hover{border-color:var(--lime)}.choice:disabled{opacity:.4}.choice strong{font-size:11px}.choice small{display:block;color:var(--muted);font-size:9px;margin-top:3px}.choice .stats{font:9px var(--mono);color:var(--lime);text-align:right}.modal-close{background:transparent;border:1px solid #45513f;border-radius:6px;padding:7px 12px;color:var(--muted)}.modal-actions{display:flex;justify-content:flex-end;gap:8px;margin-top:12px}.gameover{color:var(--red)}
 @media(max-width:900px){.main-grid{grid-template-columns:minmax(0,1.25fr) minmax(280px,.85fr)}.app{padding:16px}.map-wrap,.map-canvas{min-height:280px}.cards{grid-template-columns:1fr}.action-card{display:grid;grid-template-columns:27px 1fr auto;align-items:center;padding:8px 10px}.card-icon{margin:0}.action-card p{grid-column:2;min-height:0}.card-meta{grid-column:3;grid-row:1/3;display:grid;gap:3px;border:0;margin:0;padding:0;text-align:right}.secondary-grid{grid-template-columns:1fr}}

